import "finance.malloy"

// Tier-2 analysis: naive same-period extrapolation of governed kp:TotalSales /
// kp:Margin. 2024 data covers 2024-01-01..2024-04-20 only.
run: finance_order -> {
  where: DT >= @2023-01-01 and DT <= @2024-04-20
  aggregate:
    fy2023_revenue  is net_revenue  { where: DT.year = @2023 }
    ytd2023_revenue is net_revenue  { where: DT <= @2023-04-20 }
    ytd2024_revenue is net_revenue  { where: DT.year = @2024 }
    fy2023_profit   is gross_profit { where: DT.year = @2023 }
    ytd2023_profit  is gross_profit { where: DT <= @2023-04-20 }
    ytd2024_profit  is gross_profit { where: DT.year = @2024 }
} -> {
  select:
    ytd_revenue_growth is ytd2024_revenue / ytd2023_revenue - 1
    ytd_share_of_fy2023 is ytd2023_revenue / fy2023_revenue
    projected_2024_revenue is fy2023_revenue * (ytd2024_revenue / ytd2023_revenue)
    projected_2024_profit is fy2023_profit * (ytd2024_profit / ytd2023_profit)
}
